components.css:
.ds-fm-card {
  display: flex;
  flex-direction: column;
  background: #fffcf7;
  color: #241d18;
  border: 1px solid #e6d2b2;
  border-radius: 0.75rem;
  box-shadow: 0 1px 0 rgba(61, 43, 28, 0.05), 0 12px 30px rgba(61, 43, 28, 0.07);
  overflow: hidden;
  text-align: left;
  max-width: 22rem;
}
.ds-fm-card-media {
  position: relative;
  width: 100%;
  aspect-ratio: 5 / 4;
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    repeating-linear-gradient(-18deg, transparent, transparent 11px, rgba(230, 210, 178, 0.35) 11px, rgba(230, 210, 178, 0.35) 12px),
    color-mix(in srgb, #f8f3ea 70%, #e6d2b2);
}
.ds-fm-card-media-label {
  font-family: "Landars Gilroy", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #80603d;
}
.ds-fm-card-body {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: 1rem;
}
.ds-fm-card-headline {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
}
.ds-fm-card-name {
  margin: 0;
  font-family: "Landars Britannic", "Arial Narrow", "Helvetica Neue Condensed", sans-serif;
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: #241d18;
}
.ds-fm-card-price {
  font-family: "Landars Gilroy", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 1.375rem;
  font-weight: 700;
  color: #a67b46;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.ds-fm-card-portion {
  margin: 0;
  font-family: "Landars Gilroy", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #80603d;
}
.ds-fm-card-description {
  margin: 0;
  font-family: "Landars Gilroy", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 0.9375rem;
  line-height: 1.5;
  color: #5f5147;
}
.ds-fm-card-detail, .ds-fm-card-allergens {
  margin: 0;
  font-family: "Landars Gilroy", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 0.8125rem;
  line-height: 1.5;
  color: #5f5147;
}
.ds-fm-card-allergens { color: #806f60; }
.ds-fm-card-detail-label {
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #80603d;
  font-size: 0.6875rem;
}
.ds-fm-card:focus-within {
  outline: 2px solid #80603d;
  outline-offset: 3px;
}

.ds-fm-nav {
  display: flex;
  gap: 0.375rem;
  background: color-mix(in srgb, #f8f3ea 94%, white);
  border-bottom: 1px solid color-mix(in srgb, #e6d2b2 85%, transparent);
  padding: 0.5rem;
}
.ds-fm-nav-link {
  appearance: none;
  flex: 0 0 auto;
  min-height: 2.75rem;
  min-width: 2.75rem;
  padding: 0.5rem 0.875rem;
  border-radius: 0.375rem;
  border: 1px solid transparent;
  background: transparent;
  color: #5f5147;
  font-family: "Landars Gilroy", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 0.8125rem;
  font-weight: 600;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  cursor: pointer;
  transition: color 140ms cubic-bezier(0.22, 1, 0.36, 1), background 140ms cubic-bezier(0.22, 1, 0.36, 1), border-color 140ms cubic-bezier(0.22, 1, 0.36, 1);
}
.ds-fm-nav-link:hover {
  color: #241d18;
  background: color-mix(in srgb, #fffcf7 80%, #f8f3ea);
}
.ds-fm-nav-link[aria-current="true"] {
  color: #241d18;
  background: #fffcf7;
  border-color: #e6d2b2;
}
.ds-fm-nav-link:focus-visible {
  outline: 2px solid #80603d;
  outline-offset: 3px;
}

.ds-fm-retry {
  min-height: 2.75rem;
  padding: 0.5rem 1.25rem;
  border-radius: 0.375rem;
  border: 1px solid #e6d2b2;
  background: #fffcf7;
  color: #241d18;
  font-family: "Landars Gilroy", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: border-color 140ms cubic-bezier(0.22, 1, 0.36, 1), background 140ms cubic-bezier(0.22, 1, 0.36, 1);
}
.ds-fm-retry:hover {
  border-color: #d7c2a2;
  background: color-mix(in srgb, #d7c2a2 14%, #fffcf7);
}
.ds-fm-retry:focus-visible {
  outline: 2px solid #80603d;
  outline-offset: 3px;
}
.ds-fm-retry:active {
  background: color-mix(in srgb, #d7c2a2 22%, #fffcf7);
}

.ds-fm-offer {
  margin: 0 auto;
  max-width: 36rem;
  padding: 0.7rem 0.5rem;
  border-top: 1.5px solid #e6d2b2;
  border-bottom: 1.5px solid #e6d2b2;
  background: transparent;
  font-family: "Landars Gilroy", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 0.8125rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  line-height: 1.45;
  color: #a67b46;
  text-align: center;
}

.ds-fm-additions {
  margin: 0;
  padding: 0.625rem 0;
  border-top: 1px solid #e6d2b2;
  border-bottom: 1px solid #e6d2b2;
  background: transparent;
}
.ds-fm-additions-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.35rem 1.25rem;
}
.ds-fm-additions-list li {
  font-family: "Landars Gilroy", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #80603d;
}

.ds-fm-divider {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: #d7c2a2;
  margin: 0.35rem 0;
}
.ds-fm-divider-line {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, transparent, #e6d2b2 18%, #e6d2b2 82%, transparent);
}
.ds-fm-divider-mark {
  display: inline-flex;
  color: #d7c2a2;
}

.ds-fm-well {
  width: 100%;
  max-width: 18rem;
  aspect-ratio: 5 / 4;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 0.75rem 0.75rem 0 0;
  background:
    repeating-linear-gradient(-18deg, transparent, transparent 11px, rgba(230, 210, 178, 0.35) 11px, rgba(230, 210, 178, 0.35) 12px),
    color-mix(in srgb, #f8f3ea 70%, #e6d2b2);
}
.ds-fm-well-label {
  font-family: "Landars Gilroy", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #80603d;
}

.ds-fm-state {
  max-width: 24rem;
  margin: 0 auto;
  padding: 1.75rem 1.25rem;
  text-align: center;
  border-radius: 0.75rem;
  background: #fffcf7;
  border: 1px solid #e6d2b2;
  box-shadow: 0 1px 0 rgba(61, 43, 28, 0.05), 0 12px 30px rgba(61, 43, 28, 0.07);
}
.ds-fm-state-title {
  margin: 0 0 0.5rem;
  font-family: "Landars Britannic", "Arial Narrow", "Helvetica Neue Condensed", sans-serif;
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #241d18;
}
.ds-fm-state-body {
  margin: 0;
  font-family: "Landars Gilroy", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 0.875rem;
  color: #5f5147;
  line-height: 1.45;
}

.ds-fm-choices {
  margin-top: 0.25rem;
  padding-top: 0.625rem;
  border-top: 1px solid #e6d2b2;
}
.ds-fm-choice-label {
  margin: 0 0 0.5rem;
  font-family: "Landars Gilroy", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #80603d;
}
.ds-fm-choice-list {
  margin: 0;
  padding: 0;
  list-style: none;
}
.ds-fm-choice-list > li {
  padding: 0.55rem 0;
  border-bottom: 1px solid #e6d2b2;
}
.ds-fm-choice-list > li:last-child {
  border-bottom: none;
  padding-bottom: 0;
}
.ds-fm-choice-name {
  margin: 0;
  font-family: "Landars Gilroy", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.3;
  color: #241d18;
}
.ds-fm-choice-description {
  margin: 0.2rem 0 0;
  font-family: "Landars Gilroy", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 0.90625rem;
  line-height: 1.45;
  color: #5f5147;
}
